<template>
  <main class="app-container pc-page">
    <h1>连接与模型</h1><p class="pc-muted">登记工作区、Runner、供应商与扩展。配置不直接授予执行权限，密钥只使用受控引用。</p>
    <div class="pc-toolbar"><label for="pc-connections-workspace">工作区</label><el-select id="pc-connections-workspace" v-model="workspaceId" :disabled="busy"><el-option v-for="workspace in workspaces" :key="workspace.id" :value="workspace.id" :label="workspace.name" /></el-select><el-button v-hasPermi="['paicli:workspace:manage']" @click="workspaceOpen = true">登记工作区</el-button><el-button :loading="loading" @click="reload">刷新全部配置</el-button></div>
    <el-alert v-if="workspaceError || pageError || error" :title="workspaceError || pageError || error" type="error" :closable="false" /><OperationTask :task-id="operationTaskId" :workspace-id="workspaceId" :title="operationTitle" @settled="operationSettled" />
    <el-tabs v-model="tab"><el-tab-pane label="检索与向量配置" name="knowledge"><WorkspaceKnowledgeConfig :workspace="currentWorkspace" @saved="reload" /></el-tab-pane>
      <el-tab-pane label="设备与成员" name="runner"><RunnerBinding v-if="checkPermi(['paicli:runner:list'])" :workspace-id="workspaceId" :runners="runners" @refresh="loadWorkspaceData" /><section v-if="currentWorkspace && checkPermi(['paicli:workspace:manage'])" class="pc-panel"><h2>工作区成员与数据边界</h2><p class="pc-muted">根目录 {{ currentWorkspace.rootPath }}；指纹 {{ currentWorkspace.rootFingerprint }}。成员与批准者由中心校验，部门权限不自动替代工作区成员关系。</p><el-table :data="members"><el-table-column prop="userId" label="若依用户 ID" /><el-table-column prop="userName" label="用户" /><el-table-column label="职责"><template #default="{ row }">{{ memberRoleName(row.role) }}</template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button v-hasPermi="['paicli:workspace:manage']" link type="danger" :disabled="busy" @click="removeWorkspaceMember(row)">移除成员</el-button></template></el-table-column></el-table><el-form inline class="pc-actions"><el-form-item label="若依用户 ID"><el-input v-model="memberForm.userId" /></el-form-item><el-form-item label="职责"><el-select v-model="memberForm.role" style="width:180px"><el-option v-for="(label,value) in memberRoles" :key="value" :label="label" :value="value" /></el-select></el-form-item><el-button v-hasPermi="['paicli:workspace:manage']" :loading="busy" :disabled="!memberForm.userId" @click="addWorkspaceMember">分配成员</el-button></el-form></section></el-tab-pane>
      <el-tab-pane label="供应商与模型" name="models"><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!workspaceId" @click="editProvider()">登记供应商</el-button><el-alert title="完整供应商与模型列表来自中心登记；模型刷新只追加，失败保留原配置。未知模型默认 128k 文本，能力须按已核实模板登记。" type="info" :closable="false" /><el-table :data="providers"><el-table-column prop="name" label="供应商" width="140" /><el-table-column label="协议" width="130"><template #default="{ row }">{{ protocolName(row.protocol) }}</template></el-table-column><el-table-column prop="baseUrl" label="服务地址" min-width="250" /><el-table-column label="密钥状态" width="130"><template #default="{ row }">{{ row.secretConfigured ? '已配置（不回显）' : '未配置' }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }">{{ stateName(row.status) }}<p v-if="row.lastError" class="pc-muted">{{ row.lastError }}</p></template></el-table-column><el-table-column label="操作" width="280"><template #default="{ row }"><el-button v-hasPermi="['paicli:connection:manage']" link @click="editProvider(row)">配置</el-button><el-button v-hasPermi="['paicli:workspace:manage']" link :disabled="busy || currentWorkspace?.defaultProviderId===row.id" @click="setDefaultProvider(row)">{{currentWorkspace?.defaultProviderId===row.id ? '当前默认' : '设为工作区默认'}}</el-button><el-button v-hasPermi="['paicli:connection:manage']" link :disabled="busy || !row.secretConfigured" @click="refreshProvider(row)">刷新模型</el-button></template></el-table-column></el-table><div class="pc-actions"><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!providers.length" @click="editModel()">添加模型</el-button></div><el-table :data="models"><el-table-column prop="modelId" label="完整模型 ID" min-width="280" /><el-table-column label="供应商"><template #default="{ row }">{{ providers.find(item => item.id === row.providerId)?.name || row.providerId }}</template></el-table-column><el-table-column prop="contextWindow" label="上下文 Token" width="150" /><el-table-column label="能力" min-width="200"><template #default="{ row }">{{ row.supportsImages ? '图片 / ' : '' }}{{ row.supportsThinking ? '思考 / ' : '' }}{{ row.supportsTools ? '工具 / ' : '' }}文本<el-tag v-if="!row.capabilityKnown" type="warning">未知能力</el-tag></template></el-table-column><el-table-column label="启用"><template #default="{ row }">{{ row.enabled ? '可选' : '未启用' }}</template></el-table-column><el-table-column label="配置" width="130"><template #default="{ row }"><el-button v-hasPermi="['paicli:connection:manage']" link @click="editModel(row)">能力与预算</el-button></template></el-table-column></el-table><el-empty v-if="!models.length" description="没有已登记模型，请先配置供应商" /></el-tab-pane>
      <el-tab-pane label="MCP 服务 / 资源 / 提示词" name="mcp"><el-alert title="项目 MCP 变更需要对当前配置哈希重新批准信任；stdio 属于代码执行，未验证隔离时不能启动。OAuth、sampling、自动恢复尚未承诺。" type="warning" :closable="false" /><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!workspaceId" @click="editMcp()">登记 MCP 服务</el-button><el-table :data="mcpServers"><el-table-column prop="name" label="服务" /><el-table-column label="来源 / 传输"><template #default="{ row }">{{ row.scope === 'PROJECT' ? '项目' : '当前用户' }} / {{ row.transport }}</template></el-table-column><el-table-column label="状态 / 信任"><template #default="{ row }">{{ stateName(row.status) }}<p class="pc-muted">{{ row.configHash === row.trustedHash ? '当前配置已批准信任' : '需确认当前配置' }}</p><p v-if="row.error">{{ row.error }}</p></template></el-table-column><el-table-column label="操作" min-width="370"><template #default="{ row }"><el-button link @click="viewMcp(row)">工具 / 资源 / 提示</el-button><el-button v-hasPermi="['paicli:connection:manage']" link @click="editMcp(row)">修改配置</el-button><el-button v-hasPermi="['paicli:connection:manage']" link :disabled="busy || row.configHash !== row.trustedHash" @click="actMcp(row,'START')">启动</el-button><el-button v-hasPermi="['paicli:connection:manage']" link :disabled="busy" @click="actMcp(row,'STOP')">停止</el-button><el-button v-hasPermi="['paicli:connection:manage']" link :disabled="busy || row.configHash !== row.trustedHash" @click="actMcp(row,'RESTART')">重启</el-button><el-button link @click="mcpLogs(row)">日志</el-button></template></el-table-column></el-table><el-empty v-if="!mcpServers.length" description="没有已登记 MCP 服务" /></el-tab-pane>
      <el-tab-pane label="浏览器与 CDP" name="browser"><section class="pc-panel"><h2>当前浏览器连接</h2><p v-if="browser">{{ browser.connected ? '已连接' : '未连接' }} · {{ browser.mode }} · {{ browser.endpoint }}</p><p v-if="browser" class="pc-muted">最近探活 {{ displayTime(browser.lastProbeAt) }} · 版本 {{ browser.version }}</p><el-alert v-if="browser?.error" :title="browser.error" type="error" :closable="false" /><el-form label-width="130px"><el-form-item label="目标模式"><el-select v-model="browserForm.mode"><el-option label="独立隔离浏览器" value="ISOLATED" /><el-option label="共享登录态（须确认）" value="SHARED" /><el-option label="断开" value="DISCONNECTED" /></el-select></el-form-item><el-form-item v-if="browserForm.mode !== 'DISCONNECTED'" label="受控 MCP 配置"><el-select v-model="browserForm.mcpConfigId" placeholder="同工作区已信任 chrome-devtools"><el-option v-for="server in mcpServers.filter(item=>item.name === 'chrome-devtools' && item.configHash === item.trustedHash)" :key="server.id" :label="`${server.name} · 版本 ${server.version}`" :value="server.id" /></el-select></el-form-item><el-form-item label="CDP 地址"><el-input v-model="browserForm.endpoint" placeholder="显式登记的本机 CDP 端点" /></el-form-item><el-form-item v-if="browserForm.mode === 'SHARED'" label="登录态影响"><el-checkbox v-model="browserForm.confirmShared">已确认连接常用浏览器；敏感写入仍须逐次批准</el-checkbox></el-form-item></el-form><div class="pc-actions"><el-button v-hasPermi="['paicli:connection:manage']" :loading="busy" :disabled="!browser?.id" @click="probe">探活当前连接</el-button><el-button v-hasPermi="['paicli:connection:manage']" type="primary" :loading="busy" :disabled="!browser || (browserForm.mode === 'SHARED' && !browserForm.confirmShared)" @click="saveBrowser">保存目标连接配置</el-button><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!browser?.id" :loading="busy" @click="actBrowser('CONNECT')">连接已登记目标</el-button><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!browser?.id" :loading="busy" @click="actBrowser('TABS')">查询实际标签页</el-button><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!browser?.id" :loading="busy" @click="actBrowser('DISCONNECT')">断开当前连接</el-button></div><p class="pc-muted">保存配置后须连接或探活，中心回执才表示成功；isolated 不加载用户常用 profile，shared 登录态不能绕审批。</p><p v-if="browser?.tabsStatus" class="pc-muted">标签页回执：{{stateName(browser.tabsStatus)}}</p><el-empty v-if="browser?.tabs && !browser.tabs.length" description="Runner 已确认当前没有标签页" /><el-alert v-if="browser && !browser.tabs" title="尚无可解析的标签页列表，请查询实际标签页并核对任务回执。" type="info" :closable="false" /><el-collapse v-if="browser?.tabsResult"><el-collapse-item title="最近标签页原始回执"><pre class="pc-pre">{{safeText(browser.tabsResult)}}</pre></el-collapse-item></el-collapse><el-table v-if="browser?.tabs?.length" :data="browser.tabs"><el-table-column prop="id" label="标签页 ID" /><el-table-column prop="title" label="实际标题" /><el-table-column prop="url" label="实际地址" min-width="260" /></el-table></section></el-tab-pane>
      <el-tab-pane label="Skills" name="skills"><el-alert title="builtin → user → project 同名覆盖，只展示实际生效版本；Skill 内容不能扩大权限。索引和正文均由 Runner 校验。" type="info" :closable="false" /><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!workspaceId" :loading="busy" @click="reloadSkillList">重载 Skills</el-button><el-table :data="skills"><el-table-column prop="name" label="Skill" /><el-table-column prop="description" label="描述" min-width="230" /><el-table-column prop="scope" label="来源" width="120" /><el-table-column label="状态" width="180"><template #default="{ row }">{{ row.enabled ? '已启用' : '已停用' }} · {{ row.effective ? '生效版本' : '已被覆盖' }}</template></el-table-column><el-table-column label="操作" width="180"><template #default="{ row }"><el-button link @click="showSkill(row.id)">查看正文</el-button><el-button v-hasPermi="['paicli:connection:manage']" link :disabled="busy" @click="toggleSkill(row)">{{ row.enabled ? '停用' : '启用' }}</el-button></template></el-table-column></el-table><el-empty v-if="!skills.length" description="未加载可用 Skills" /></el-tab-pane>
      <el-tab-pane label="微信 iLink 文本" name="wechat"><el-alert title="微信仅提供文本通道。必须绑定若依用户与唯一工作区；没有审批面板的未知写入默认拒绝，二维码登录不等于已有任务授权。" type="warning" :closable="false" /><section class="pc-panel"><el-descriptions v-if="wechat" :column="1" border><el-descriptions-item label="状态">{{ stateName(wechat.status) }}</el-descriptions-item><el-descriptions-item label="若依身份 / sender">{{ wechat.boundUserName || '未绑定' }} / {{ wechat.senderMasked || '未绑定' }}</el-descriptions-item><el-descriptions-item label="日预算">{{ wechat.dailyUsed }} / {{ wechat.dailyBudget }} Token</el-descriptions-item><el-descriptions-item label="当前队列">{{ wechat.queueSize }}</el-descriptions-item></el-descriptions><el-alert v-if="wechat?.lastError" :title="wechat.lastError" type="error" :closable="false" /><div class="pc-actions"><el-button v-hasPermi="['paicli:connection:manage']" :loading="busy" :disabled="!workspaceId" @click="setupWechatChannel">申请登录二维码</el-button><el-button v-if="wechat?.qrArtifactId" @click="showQr">查看当前二维码</el-button><el-button v-if="wechat" v-hasPermi="['paicli:connection:manage']" @click="openWechatBinding">绑定用户与 sender</el-button><el-button v-for="action in wechatActions" v-if="wechat" :key="action.value" v-hasPermi="['paicli:connection:manage']" :disabled="busy || !wechat.boundUserName" @click="actWechat(action.value)">{{ action.label }}</el-button></div><p class="pc-muted">start/status/pause/resume/stop/restart 只管理当前文本通道，控制命令与消息预算由中心裁决。</p></section><WechatPolicy v-if="wechat" :channel="wechat" :mcp-names="mcpServers.map(server=>server.name)" @saved="loadWorkspaceData" /></el-tab-pane>
      <el-tab-pane label="预算、策略与保留" name="policy"><section v-if="policy" class="pc-panel"><h2>工作区策略版本 {{ policy.version }}</h2><el-alert title="确定性硬拒绝不能由配置或人工批准解除；当前命令执行必须使用已验证隔离环境。" type="warning" :closable="false" /><el-form label-width="180px"><el-form-item label="自动用户原话候选"><el-switch v-model="policy.autoFactExtractionEnabled" /></el-form-item><el-form-item label="自动上下文压缩"><el-switch v-model="policy.autoCompactionEnabled" /></el-form-item><el-form-item label="会话历史记忆辅助"><el-switch v-model="policy.sessionMemoryEnabled" /></el-form-item><el-form-item label="每用户活跃会话"><el-input-number v-model="policy.maxActiveSessions" :min="1" :max="10" /></el-form-item><el-form-item label="队列上限"><el-input-number v-model="policy.maxQueuedTasks" :min="1" :max="100" /></el-form-item><el-form-item label="只读工具并行数"><el-input-number v-model="policy.maxReadTools" :min="1" :max="4" /></el-form-item><el-form-item label="写任务并行数"><el-input-number v-model="policy.maxWriteTasks" :min="1" :max="1" /></el-form-item><el-form-item label="命令超时（秒）"><el-input-number v-model="policy.commandTimeoutSeconds" :min="1" :max="60" /></el-form-item><el-form-item label="审批超时（秒）"><el-input-number v-model="policy.approvalTimeoutSeconds" :min="60" :max="900" /></el-form-item><el-form-item label="每任务 Token 预算"><el-input-number v-model="policy.taskTokenBudget" :min="1" /></el-form-item><el-form-item label="每日 Token 预算"><el-input-number v-model="policy.dailyTokenBudget" :min="1" /></el-form-item><el-form-item label="数据保留（天）"><el-input-number v-model="policy.retentionDays" :min="1" /></el-form-item></el-form><h3>硬拒绝路径</h3><pre class="pc-pre">{{ policy.hardDeniedPaths.join('\n') }}</pre><h3>可申请能力</h3><pre class="pc-pre">{{ policy.allowedCapabilities.join('\n') }}</pre><el-button v-hasPermi="['paicli:connection:manage']" type="primary" :loading="busy" @click="saveWorkspacePolicy">保存策略版本</el-button></section><el-empty v-else description="当前工作区策略不可用" /></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="workspaceOpen" title="登记独立业务工作区" width="650px" class="pc-dialog"><el-form label-width="130px"><el-form-item label="工作区名称"><el-input v-model="workspaceForm.name" /></el-form-item><el-form-item label="授权根目录"><el-input v-model="workspaceForm.rootPath" /></el-form-item><el-form-item label="根目录 SHA-256"><el-input v-model="workspaceForm.rootFingerprint" /></el-form-item><el-form-item label="描述"><el-input v-model="workspaceForm.description" type="textarea" /></el-form-item></el-form><el-alert title="登记不读取服务端目录；目标 Runner 校验真实根目录。禁止系统盘根、密钥或其他业务安装目录。" type="warning" :closable="false" /><el-alert v-if="error" :title="error" type="error" :closable="false" /><template #footer><el-button @click="workspaceOpen = false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!workspaceForm.name || !workspaceForm.rootPath || !/^[0-9a-f]{64}$/i.test(workspaceForm.rootFingerprint)" @click="registerWorkspace">登记</el-button></template></el-dialog>
    <el-dialog v-model="providerOpen" title="供应商受控配置" width="650px" class="pc-dialog"><el-form label-width="130px"><el-form-item label="供应商"><el-select v-model="providerForm.name" :disabled="!!providerForm.id"><el-option v-for="provider in providerNames" :key="provider" :label="provider" :value="provider" /></el-select></el-form-item><el-form-item label="协议">供应商原生协议适配</el-form-item><el-form-item label="地址"><el-input v-model="providerForm.baseUrl" /></el-form-item><el-form-item label="默认启动模型"><el-input v-model="providerForm.model" placeholder="完整模型 ID，不改变当前会话模型" /></el-form-item><el-form-item label="LoRA ID"><el-input v-model="providerForm.loraId" placeholder="原供应商适配支持的 LoRA ID" /></el-form-item><el-form-item v-hasPermi="['paicli:secret:write']" label="受控密钥引用"><el-input v-model="providerForm.secretRef" autocomplete="off" placeholder="引用已批准的密钥记录，不能输入 Key 正文" /></el-form-item></el-form><el-alert title="网页不保存或回显供应商 Key；只向中心提交受控引用，密钥管理需独立权限。" type="info" :closable="false" /><el-alert v-if="error" :title="error" type="error" :closable="false" /><template #footer><el-button @click="providerOpen = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveProviderConfig">保存</el-button></template></el-dialog>
    <el-dialog v-model="modelOpen" :title="modelForm.id ? '修改模型能力与预算' : '添加模型'" width="650px" class="pc-dialog"><el-form label-width="140px"><el-form-item label="供应商"><el-select v-model="modelForm.providerId" :disabled="!!modelForm.id" @change="templateModelId = ''"><el-option v-for="provider in providers" :key="provider.id" :value="provider.id" :label="provider.name" /></el-select></el-form-item><el-form-item label="完整模型 ID"><el-input v-model="modelForm.modelId" /></el-form-item><el-form-item label="已核实同厂模板"><el-select v-model="templateModelId" clearable placeholder="不选模板则 128k 文本未知能力" @change="applyModelTemplate"><el-option v-for="model in models.filter(item => item.providerId === modelForm.providerId && item.capabilityKnown)" :key="model.id" :value="model.id" :label="model.modelId" /></el-select></el-form-item><el-form-item label="上下文 Token"><el-input-number v-model="modelForm.contextWindow" :min="8000" :max="10000000" /></el-form-item><el-form-item label="输出 Token 上限"><el-input-number v-model="modelForm.maxOutputTokens" :min="1" :max="Math.min(1000000,modelForm.contextWindow || 1000000)" controls-position="right" /><span class="pc-muted"> 留空沿用模板</span></el-form-item><el-form-item label="实际能力"><el-checkbox v-model="modelForm.supportsImages">图片</el-checkbox><el-checkbox v-model="modelForm.supportsTools">工具调用</el-checkbox><el-checkbox v-model="modelForm.capabilityKnown">已核验能力</el-checkbox></el-form-item><el-form-item label="思考模式"><el-select v-model="modelForm.thinking" clearable placeholder="沿用模板"><el-option label="启用" value="enabled" /><el-option label="停用" value="disabled" /></el-select></el-form-item><el-form-item label="思考强度"><el-select v-model="modelForm.reasoningEffort" clearable placeholder="沿用模板"><el-option v-for="effort in ['low','medium','high','max']" :key="effort" :label="effort" :value="effort" /></el-select></el-form-item><el-form-item label="推理历史"><el-select v-model="modelForm.reasoningHistory" clearable placeholder="沿用模板"><el-option label="续轮回传" :value="true" /><el-option label="不回传" :value="false" /></el-select></el-form-item><el-form-item label="DSML 解析"><el-select v-model="modelForm.dsml" clearable placeholder="沿用模板"><el-option label="启用已支持解析" :value="true" /><el-option label="停用" :value="false" /></el-select></el-form-item><el-form-item label="模型可选"><el-checkbox v-model="modelForm.enabled">在当前工作区启用</el-checkbox></el-form-item></el-form><el-alert v-if="error" :title="error" type="error" :closable="false" /><template #footer><el-button @click="modelOpen = false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!modelForm.providerId || !modelForm.modelId.trim()" @click="saveModel">保存模型配置</el-button></template></el-dialog>
