async function removeWorkspaceMember(member: PcMember) { const workspace = currentWorkspace.value; if (!workspace) return; try { await ElMessageBox.confirm(`移除 ${member.userName} 在 ${workspace.name} 的工作区权限，确认继续？`,'移除成员',{ type:'warning' }) } catch { return }; if (workspace.id !== workspaceId.value) return; const intent = { action:'remove-member',id:workspace.id,userId:member.userId,version:workspace.version }; await run(async () => { await removeMember(intent.id,member.userId,intent.version,keys.get(intent)); keys.done(intent); await loadWorkspaces(); await loadWorkspaceData() }) }
