async function saveProviderConfig() { const data = { ...providerForm,model:providerForm.model?.trim() || undefined,loraId:providerForm.loraId?.trim() || undefined,workspaceId:workspaceId.value }; await run(async () => { await saveProvider(data,keys.get(data)); keys.done(data); providerOpen.value = false; await reload() }) }
async function setDefaultProvider(provider:PcProvider){const workspace=currentWorkspace.value;if(!workspace || !checkPermi(['paicli:workspace:manage']))return;const data={...workspace,defaultProviderId:provider.id};await run(async()=>{await saveWorkspace(data,keys.get(data));keys.done(data);await loadWorkspaces()})}
async function refreshProvider(provider: PcProvider) { const intent = { action:'refresh',id:provider.id,version:provider.version }; await run(async () => { trackTask((await refreshModels(provider.id,provider.version,keys.get(intent))).data,'刷新供应商模型'); keys.done(intent); await reload() }) }
