function editModel(model?: PcModel) { for(const field of Object.keys(modelForm))delete(modelForm as Record<string,unknown>)[field]; Object.assign(modelForm,model ? {...model} : {providerId:providers.value[0]?.id || '',modelId:'',contextWindow:128000,supportsImages:false,supportsThinking:false,supportsTools:false,capabilityKnown:false,enabled:true}); templateModelId.value='';modelOpen.value=true;error.value='' }
function trackTask(data: PcTask | PcMcpServer | PcWechat, title: string) { if('mode' in data && data.mode==='CONTROL'){operationTaskId.value=data.id;operationTitle.value=title} }
async function operationSettled(task: PcTaskDetail) { if(task.workspaceId === workspaceId.value)await loadWorkspaceData() }
async function actBrowser(action:'TABS'|'CONNECT'|'DISCONNECT') { const current=browser.value;if(!current?.id)return;const intent={id:current.id,version:current.version,action};await run(async()=>{trackTask((await browserAction(intent.id,intent.version,action,keys.get(intent))).data,`浏览器 ${action}`);keys.done(intent)}) }
function isPromptDefinition(prompt: unknown): prompt is PcMcpPromptDefinition {
  if (!prompt || typeof prompt !== 'object' || !('name' in prompt) || typeof prompt.name !== 'string' || !prompt.name.trim()) return false
  if (!('arguments' in prompt) || prompt.arguments === undefined) return true
