}
function viewMcp(server: PcMcpServer) { selectedMcp.value = server; mcpContent.value = undefined; mcpLog.value = []; mcpDetailOpen.value = true }
async function actMcp(server: PcMcpServer,action: 'START'|'STOP'|'RESTART'|'TRUST') { if (action === 'TRUST') { try { await ElMessageBox.confirm(`信任 ${server.name} 本次配置哈希 ${server.configHash}。stdio 执行代码仍须隔离和操作批准，确认已核对来源？`,'信任当前 MCP 配置',{ type:'warning' }) } catch { return } }; const intent = { id:server.id,action,version:server.version,configHash:server.configHash }; await run(async () => { trackTask((await mcpAction(server.id,action,server.version,server.configHash,keys.get(intent))).data,`MCP ${server.name} ${action}`); keys.done(intent); await loadWorkspaceData(); selectedMcp.value = mcpServers.value.find(item => item.id === server.id) }) }
async function mcpLogs(server: PcMcpServer) { viewMcp(server); await run(async () => { mcpLog.value = (await getMcpLogs(server.id)).data }) }
async function readMcp(kind: 'resource'|'prompt',reference: string) { const id = selectedMcp.value?.id; if (!id || typeof reference!=='string' || !reference.trim() || (kind==='prompt'&&!hasPromptReference(reference))) return; await run(async () => { const response = await getMcpContent(id,kind,reference); if (id === selectedMcp.value?.id) mcpContent.value = response.data }) }
async function probe() { const id = workspaceId.value,intent = { action:'probe',id }; await run(async () => { const response = await probeBrowser(id,keys.get(intent)); keys.done(intent); trackTask(response.data,'浏览器探活'); if (id === workspaceId.value) await loadWorkspaceData() }) }
async function saveBrowser() { if (!browser.value) return; const data = { ...browserForm,workspaceId:workspaceId.value,version:browser.value.version }; await run(async () => { await updateBrowser(data,keys.get(data)); keys.done(data); await loadWorkspaceData() }) }
async function showSkill(id: string) { await run(async () => { selectedSkill.value = (await getSkill(id)).data; skillOpen.value = true }) }
async function toggleSkill(skill: PcSkill) { const intent = { id:skill.id,version:skill.version,enabled:!skill.enabled }; await run(async () => { trackTask((await setSkillEnabled(skill.id,!skill.enabled,skill.version,keys.get(intent))).data,`Skill ${skill.name} 配置生效`); keys.done(intent); await loadWorkspaceData() }) }
async function reloadSkillList() { const id = workspaceId.value,intent = { action:'reload-skills',id }; await run(async () => { trackTask((await reloadSkills(id,keys.get(intent))).data,'重载 Skills'); keys.done(intent); await loadWorkspaceData() }) }
async function setupWechatChannel() { const id = workspaceId.value,intent = { action:'wechat-setup',id }; await run(async () => { wechat.value = (await setupWechat(id,keys.get(intent))).data; if(wechat.value?.taskId){operationTaskId.value=wechat.value.taskId;operationTitle.value='微信登录二维码'}; keys.done(intent) }) }
function openWechatBinding(){wechatBinding.modelId=wechat.value?.modelId || '';wechatBinding.dailyBudget=wechat.value?.dailyBudget || 100000;wechatBindingOpen.value=true}
async function bindWechatIdentity() { const channel = wechat.value; if (!channel) return; const data = { ...wechatBinding,modelId:wechatBinding.modelId || undefined,workspaceId:workspaceId.value,version:channel.version },intent = { id:channel.id,...data }; await run(async () => { await bindWechat(channel.id,data,keys.get(intent)); keys.done(intent); wechatBindingOpen.value = false; wechatBinding.sender = ''; await loadWorkspaceData() }) }
async function actWechat(action: 'START'|'PAUSE'|'RESUME'|'STOP'|'RESTART') { const channel = wechat.value; if (!channel) return; const intent = { id:channel.id,version:channel.version,action }; await run(async () => { trackTask((await wechatAction(channel.id,action,channel.version,keys.get(intent))).data,`微信通道 ${action}`); keys.done(intent); await loadWorkspaceData() }) }
function clearQr() { if (qrUrl.value) URL.revokeObjectURL(qrUrl.value); qrUrl.value = '' }
async function showQr() { const id = wechat.value?.qrArtifactId; if (!id) return; await run(async () => { const blob = await downloadArtifact(id); if (!['image/png','image/jpeg'].includes(blob.type)) throw new Error('二维码内容不是支持的图片'); clearQr(); qrUrl.value = URL.createObjectURL(blob); qrOpen.value = true }) }
async function saveWorkspacePolicy() { const data = policy.value; if (!data) return; const intent = { workspaceId:workspaceId.value,...data }; await run(async () => { await savePolicy(workspaceId.value,{ ...data },keys.get(intent)); keys.done(intent); await loadWorkspaceData() }) }
watch(workspaceId, () => { workspaceGeneration++; wechatBindingOpen.value=false; operationTaskId.value='';promptOpen.value=false; mcpOpen.value = false; clearQr(); qrOpen.value = false; selectedMcp.value = undefined; providers.value = []; models.value = []; members.value = []; runners.value = []; mcpServers.value = []; browser.value = undefined; skills.value = []; wechat.value = undefined; policy.value = undefined; if (workspaceId.value) void loadWorkspaceData() }); watch(() => modelForm.providerId,()=>{if(!modelForm.id)applyModelTemplate()})
onMounted(reload); onBeforeUnmount(() => { workspaceGeneration++; providerGeneration++; clearQr() })
</script>
<style scoped>.pc-panel + .pc-panel{margin-top:16px}.pc-mcp-prompt{overflow-wrap:anywhere}</style>
